17	package org.springframework.samples.petclinic.rest.advice;
18	
19	import java.net.URI;
20	import java.time.Instant;
21	import java.util.List;
22	import java.util.Objects;
23	
24	import jakarta.servlet.http.HttpServletRequest;
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.dao.DataIntegrityViolationException;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ProblemDetail;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.rest.controller.BindingErrorsResponse;
32	import org.springframework.samples.petclinic.rest.dto.ValidationMessageDto;
33	import org.springframework.samples.petclinic.rest.validation.CityCapacityExceededException;
34	import org.springframework.samples.petclinic.rest.validation.DailyOwnerLimitExceededException;
35	import org.springframework.samples.petclinic.rest.validation.DuplicateHouseholdException;
36	import org.springframework.samples.petclinic.rest.validation.DuplicateTelephoneException;
37	import org.springframework.samples.petclinic.rest.validation.InvalidTelephoneException;
38	import org.springframework.samples.petclinic.rest.validation.MissingOwnerFieldsException;
39	import org.springframework.security.access.AccessDeniedException;
40	import org.springframework.validation.BindingResult;
41	import org.springframework.validation.FieldError;
42	import org.springframework.web.bind.MethodArgumentNotValidException;
43	import org.springframework.web.bind.annotation.ControllerAdvice;
44	import org.springframework.web.bind.annotation.ExceptionHandler;
45	import org.springframework.web.bind.annotation.ResponseBody;
46	
47	/**
48	 * Global Exception handler for REST controllers.
49	 * <p>
50	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
51	 *
52	 * @author Vitaliy Fedoriv
53	 * @author Alexander Dudkin
54	 */
55	@ControllerAdvice
56	public class ExceptionControllerAdvice {
57	
58	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
59	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
60	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
61	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
62	    private static final String ERROR_DUPLICATE_TELEPHONE = "An owner with the given telephone number already exists";
63	    private static final String ERROR_DUPLICATE_HOUSEHOLD = "An owner with the same last name and address already exists";
64	    private static final String ERROR_CITY_AT_CAPACITY = "The owner's city has already reached its maximum number of owners";
65	    private static final String ERROR_DAILY_LIMIT_REACHED = "The maximum number of owners that may be registered today has already been reached";
66	
67	    /**
68	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
69	     * class.
70	     *
71	     * @param e     Object referring to the thrown exception.
72	     * @param status HTTP response status.
73	     * @param url URL request.
74	     */
75	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
76	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
77	        problemDetail.setType(URI.create(url.toString()));
78	        problemDetail.setTitle(e.getClass().getSimpleName());
79	        problemDetail.setDetail(detail);
80	        problemDetail.setProperty("timestamp", Instant.now());
81	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
82	        return problemDetail;
83	    }
84	
85	    /**
86	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
87	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
88	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
89	     * would catch it and report an authorization failure as a 500.
90	     *
91	     * @param e The {@link AccessDeniedException} to propagate
92	     * @throws AccessDeniedException always
93	     */
94	    @ExceptionHandler(AccessDeniedException.class)
95	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
96	        throw e;
97	    }
98	
99	    /**
100	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
101	     *
102	     * @param e The {@link Exception} to be handled
103	     * @param request {@link HttpServletRequest} object referring to the current request.
104	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
105	     */
106	    @ExceptionHandler(Exception.class)
107	    @ResponseBody
108	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
109	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
110	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
111	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
112	        return ResponseEntity.status(status).body(detail);
113	    }
114	
115	    /**
116	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
117	     * method returns a 404 Not Found status if an entity does not exist.
118	     *
119	     * @param e The {@link DataIntegrityViolationException} to be handled
120	     * @param request {@link HttpServletRequest} object referring to the current request.
121	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
122	     */
123	    @ExceptionHandler(DataIntegrityViolationException.class)
124	    @ResponseBody
125	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
126	        logger.warn("Data integrity violation at {} {}: {}",
127	            request.getMethod(),
128	            request.getRequestURI(),
129	            e.getMessage());
130	        logger.debug("Data integrity violation stacktrace", e);
131	        HttpStatus status = HttpStatus.NOT_FOUND;
132	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
133	        return ResponseEntity.status(status).body(detail);
134	    }
135	
136	    /**
137	     * Handles exception thrown by Bean Validation on controller methods parameters
138	     *
139	     * @param e The {@link MethodArgumentNotValidException} to be handled
140	     * @param request {@link HttpServletRequest} object referring to the current request.
141	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
142	     */
143	    @ExceptionHandler(MethodArgumentNotValidException.class)
144	    @ResponseBody
145	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
146	        HttpStatus status = HttpStatus.BAD_REQUEST;
147	        BindingErrorsResponse errors = new BindingErrorsResponse();
148	        BindingResult bindingResult = e.getBindingResult();
149	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
150	        if (bindingResult.hasErrors()) {
151	            errors.addAllErrors(bindingResult);
152	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
153	                .map(fieldError -> {
154	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
155	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
156	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
157	                        fieldError.getField(),
158	                        defaultMessage,
159	                        rejectedValue);
160	                    return new ValidationMessageDto(message)
161	                        .putAdditionalProperty("field", fieldError.getField())
162	                        .putAdditionalProperty("rejectedValue", rejectedValue)
163	                        .putAdditionalProperty("defaultMessage", defaultMessage);
164	                })
165	                .toList();
166	            logger.debug("Validation error at {} {}: {}",
167	                request.getMethod(),
168	                request.getRequestURI(),
169	                bindingResult.getFieldErrors());
170	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
171	            List<String> invalidFields = bindingResult.getFieldErrors().stream()
172	                .map(FieldError::getField)
173	                .distinct()
174	                .toList();
175	            detail.setProperty("errors", invalidFields);
176	            return ResponseEntity.status(status).body(detail);
177	        }
178	        return ResponseEntity.status(status).body(detail);
179	    }
180	
181	    /**
182	     * Handles {@link MissingOwnerFieldsException} raised when a request to create or update an owner
183	     * omits one or more mandatory fields, returning a 400 Bad Request whose {@code errors} array lists
184	     * the name of each missing field.
185	     *
186	     * @param e The {@link MissingOwnerFieldsException} to be handled
187	     * @param request {@link HttpServletRequest} object referring to the current request.
188	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
189	     */
190	    @ExceptionHandler(MissingOwnerFieldsException.class)
191	    @ResponseBody
192	    public ResponseEntity<ProblemDetail> handleMissingOwnerFieldsException(MissingOwnerFieldsException e, HttpServletRequest request) {
193	        HttpStatus status = HttpStatus.BAD_REQUEST;
194	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
195	        detail.setProperty("errors", e.getFields());
196	        return ResponseEntity.status(status).body(detail);
197	    }
198	
199	    /**
200	     * Handles {@link InvalidTelephoneException} raised when a submitted telephone number cannot be
201	     * converted to a valid E.164 value, returning a 400 Bad Request.
202	     *
203	     * @param e The {@link InvalidTelephoneException} to be handled
204	     * @param request {@link HttpServletRequest} object referring to the current request.
205	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
206	     */
207	    @ExceptionHandler(InvalidTelephoneException.class)
208	    @ResponseBody
209	    public ResponseEntity<ProblemDetail> handleInvalidTelephoneException(InvalidTelephoneException e, HttpServletRequest request) {
210	        HttpStatus status = HttpStatus.BAD_REQUEST;
211	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
212	        detail.setProperty("errors", List.of("telephone"));
213	        return ResponseEntity.status(status).body(detail);
214	    }
215	
216	    /**
217	     * Handles {@link DuplicateTelephoneException} raised when a new owner is submitted with a normalized
218	     * telephone number that is already used by an existing owner, returning a 409 Conflict.
219	     *
220	     * @param e The {@link DuplicateTelephoneException} to be handled
221	     * @param request {@link HttpServletRequest} object referring to the current request.
222	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
223	     */
224	    @ExceptionHandler(DuplicateTelephoneException.class)
225	    @ResponseBody
226	    public ResponseEntity<ProblemDetail> handleDuplicateTelephoneException(DuplicateTelephoneException e, HttpServletRequest request) {
227	        HttpStatus status = HttpStatus.CONFLICT;
228	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_TELEPHONE);
229	        detail.setProperty("errors", List.of("telephone"));
230	        return ResponseEntity.status(status).body(detail);
231	    }
232	
233	    /**
234	     * Handles {@link DuplicateHouseholdException} raised when a new owner shares an existing owner's
235	     * last name and address (compared case-insensitively with collapsed whitespace) without opting in
236	     * via {@code sharesHousehold}, returning a 409 Conflict.
237	     *
238	     * @param e The {@link DuplicateHouseholdException} to be handled
239	     * @param request {@link HttpServletRequest} object referring to the current request.
240	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
241	     */
242	    @ExceptionHandler(DuplicateHouseholdException.class)
243	    @ResponseBody
244	    public ResponseEntity<ProblemDetail> handleDuplicateHouseholdException(DuplicateHouseholdException e, HttpServletRequest request) {
245	        HttpStatus status = HttpStatus.CONFLICT;
246	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_HOUSEHOLD);
247	        detail.setProperty("errors", List.of("lastName", "address"));
248	        return ResponseEntity.status(status).body(detail);
249	    }
250	
251	    /**
252	     * Handles {@link CityCapacityExceededException} raised when a new owner is submitted for a city
253	     * that already holds the maximum number of owners, returning a 409 Conflict.
254	     *
255	     * @param e The {@link CityCapacityExceededException} to be handled
256	     * @param request {@link HttpServletRequest} object referring to the current request.
257	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
258	     */
259	    @ExceptionHandler(CityCapacityExceededException.class)
260	    @ResponseBody
261	    public ResponseEntity<ProblemDetail> handleCityCapacityExceededException(CityCapacityExceededException e, HttpServletRequest request) {
262	        HttpStatus status = HttpStatus.CONFLICT;
263	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_CITY_AT_CAPACITY);
264	        detail.setProperty("errors", List.of("city"));
265	        return ResponseEntity.status(status).body(detail);
266	    }
267	
268	    /**
269	     * Handles {@link DailyOwnerLimitExceededException} raised when the maximum number of owners
270	     * allowed to be registered on a single day has already been reached, returning a 429 Too Many
271	     * Requests.
272	     *
273	     * @param e The {@link DailyOwnerLimitExceededException} to be handled
274	     * @param request {@link HttpServletRequest} object referring to the current request.
275	     * @return A {@link ResponseEntity} containing the error information and a 429 Too Many Requests status.
276	     */
277	    @ExceptionHandler(DailyOwnerLimitExceededException.class)
278	    @ResponseBody
279	    public ResponseEntity<ProblemDetail> handleDailyOwnerLimitExceededException(DailyOwnerLimitExceededException e, HttpServletRequest request) {
280	        HttpStatus status = HttpStatus.TOO_MANY_REQUESTS;
281	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DAILY_LIMIT_REACHED);
282	        detail.setProperty("errors", List.of("registrationDate"));
283	        return ResponseEntity.status(status).body(detail);
284	    }
285	
286	}
