63	@RestController
64	@CrossOrigin(exposedHeaders = "errors, content-type")
65	@RequestMapping("/api")
66	public class OwnerRestControllerV1 implements OwnersApi {
67	
68	    /**
69	     * Maximum number of owners a single city may hold. A create request whose city already contains
70	     * this many owners is rejected as a conflict.
71	     */
72	    static final int MAX_OWNERS_PER_CITY = 50;
73	
74	    /**
75	     * Maximum number of owners that may be registered on a single day. A create request whose
76	     * registration date already holds this many owners is rejected with 429 Too Many Requests.
77	     */
78	    static final int MAX_OWNERS_PER_DAY = 100;
79	
80	    /**
81	     * Number of owners that may be registered on the current business day before a create/read
82	     * response flags {@code bulkSignupWarning}. Once more than this many owners exist for the day,
83	     * the warning is raised.
84	     */
85	    static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
86	
87	    private final ClinicService clinicService;
88	
89	    private final OwnerMapper ownerMapper;
90	
91	    private final PetMapper petMapper;
92	
93	    private final VisitMapper visitMapper;
94	
95	    private final OwnerAuditor ownerAuditor;
96	
97	    public OwnerRestControllerV1(ClinicService clinicService,
98	                                 OwnerMapper ownerMapper,
99	                                 PetMapper petMapper,
100	                                 VisitMapper visitMapper,
101	                                 OwnerAuditor ownerAuditor) {
102	        this.clinicService = clinicService;
103	        this.ownerMapper = ownerMapper;
104	        this.petMapper = petMapper;
105	        this.visitMapper = visitMapper;
106	        this.ownerAuditor = ownerAuditor;
107	    }
