109	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
110	    @Override
111	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
112	        Collection<Owner> owners;
113	        if (lastName != null) {
114	            owners = this.clinicService.findOwnerByLastName(lastName);
115	        } else {
116	            owners = this.clinicService.findAllOwners();
117	        }
118	        if (owners.isEmpty()) {
119	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
120	        }
121	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
122	    }
123	
124	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
125	    @Override
126	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
127	        Owner owner = this.clinicService.findOwnerById(ownerId);
128	        if (owner == null) {
129	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
130	        }
131	        return new ResponseEntity<>(toOwnerDtoWithBulkSignupWarning(owner), HttpStatus.OK);
132	    }
133	
134	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
135	    @Override
136	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
137	        ownerFieldsDto.setAddress(AddressNormalizer.normalize(ownerFieldsDto.getAddress()));
138	        List<String> missingFields = OwnerFieldsValidator.findMissingFields(ownerFieldsDto);
139	        if (!missingFields.isEmpty()) {
140	            throw new MissingOwnerFieldsException(missingFields);
141	        }
142	        HttpHeaders headers = new HttpHeaders();
143	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
144	        if (this.clinicService.countOwnersByCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
145	            throw new CityCapacityExceededException(owner.getCity());
146	        }
147	        LocalDate registrationDate = RegistrationDatePolicy.effectiveDate(owner.getRegistrationDate());
148	        if (this.clinicService.countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
149	            throw new DailyOwnerLimitExceededException(registrationDate);
150	        }
151	        String telephone = TelephoneNormalizer.normalize(owner.getTelephone());
152	        if (!this.clinicService.findOwnerByTelephone(telephone).isEmpty()) {
153	            throw new DuplicateTelephoneException(telephone);
154	        }
155	        Collection<Owner> household =
156	            this.clinicService.findOwnersInHousehold(owner.getLastName(), owner.getAddress());
157	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
158	        if (!household.isEmpty() && !sharesHousehold) {
159	            throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
160	        }
161	        owner.setTelephone(telephone);
162	        owner.setEmail(EmailNormalizer.normalize(owner.getEmail()));
163	        if (sharesHousehold) {
164	            this.clinicService.joinHousehold(owner, household);
165	        }
166	        this.clinicService.saveOwner(owner);
167	        this.ownerAuditor.ownerCreated(owner);
168	        OwnerDto ownerDto = toOwnerDtoWithBulkSignupWarning(owner);
169	        headers.setLocation(UriComponentsBuilder.newInstance()
170	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
171	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
172	    }
173	
174	    /**
175	     * Map an owner to its DTO and stamp {@code bulkSignupWarning}, which reflects whether more than
176	     * {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been registered on the current
177	     * business day.
178	     */
179	    private OwnerDto toOwnerDtoWithBulkSignupWarning(Owner owner) {
180	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
181	        LocalDate today = RegistrationDatePolicy.effectiveDate(null);
182	        ownerDto.setBulkSignupWarning(
183	            this.clinicService.countOwnersRegisteredOn(today) > BULK_SIGNUP_WARNING_THRESHOLD);
184	        return ownerDto;
185	    }
186	
187	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
188	    @Override
189	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
190	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
191	        if (currentOwner == null) {
192	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
193	        }
194	        currentOwner.setAddress(ownerFieldsDto.getAddress());
195	        currentOwner.setCity(ownerFieldsDto.getCity());
196	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
197	        currentOwner.setLastName(ownerFieldsDto.getLastName());
198	        currentOwner.setTelephone(TelephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
199	        currentOwner.setEmail(EmailNormalizer.normalize(ownerFieldsDto.getEmail()));
200	        this.clinicService.saveOwner(currentOwner);
201	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
202	    }
203	
204	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
205	    @Transactional
206	    @Override
207	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
208	        Owner owner = this.clinicService.findOwnerById(ownerId);
209	        if (owner == null) {
210	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
211	        }
212	        this.clinicService.deleteOwner(owner);
213	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
214	    }
